          help.className = 'ziphelp';
          help.innerHTML = 'e.g. 19428';
        }
      }
      var saveBtn = document.querySelector('[data-act="save-zip"]');
      if (saveBtn) saveBtn.className = 'btn full ' + (ok ? 'black' : 'gray');
      return;
    }

    if (t.id === 'storeSearch') {
      UI.storeFilter = t.value;
      render();
      var si = document.getElementById('storeSearch');
